import{z as d,x as B,o as i,c as p,q as o,j as r,D as t,d as l,s,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"循环交换与分块","description":"","frontmatter":{"title":"循环交换与分块","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/loop-interchange-tiling.md","filePath":"cs/loop-interchange-tiling.md","lastUpdated":1791413859000}'),A={name:"cs/loop-interchange-tiling.md"};function c(h,a,m,C,D,u){const n=B("Mermaid");return i(),p("div",null,[a[2]||(a[2]=o('<h1 id="循环交换与分块" tabindex="-1">循环交换与分块 <a class="header-anchor" href="#循环交换与分块" aria-label="Permalink to &quot;循环交换与分块&quot;">​</a></h1><div class="epigraph"><p>交换嵌套使最内层走连续地址；分块把迭代空间切成缓存大小的瓷砖。合法性由依赖是否被保持决定。</p><footer>—— 据 Wolf and Lam, A Loop Transformation Theory, 1991；Allen and Kennedy；龙书局部性变换整理</footer></div><p>上一课<a href="/cs/loop-unroll-peel">展开与剥离</a>复制同一嵌套。缺口是<strong>改迭代顺序</strong>：矩阵乘 <code>i,k,j</code> 对缓存极差；交换与 tiling 把重用留在 cache。<a href="/cs/inclusive-exclusive-cache">缓存层次</a> 已给局部性；本课是编译器如何改循环。依赖分析点名，别名后课补内存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>依赖：若迭代 \\(\\vec{i}\\) 写、\\(\\vec{j}\\) 读同一位置，\\(\\vec{j}-\\vec{i}\\) 是依赖向量。交换合法当置换后依赖仍在时间上向前（不把流依赖变成反方向）。分块：把矩形切成 \\(B\\times B\\)，块间顺序仍须尊重依赖。缺口是<strong>变换合法性</strong>，不是展开因子。</p><p>列主序与行主序语言不同，交换目标是使最内层 stride-1。</p><h3 id="分块不是「再展开一次」" tabindex="-1">分块不是「再展开一次」 <a class="header-anchor" href="#分块不是「再展开一次」" aria-label="Permalink to &quot;分块不是「再展开一次」&quot;">​</a></h3><p>展开不改访问序的大结构；tile 改空间局部性。二者可在瓷砖内再展开。</p><p><span class="marginnote">Wolf–Lam 1991。Lam 的 cache blocking。多面体后课把这套代数化。本课用依赖向量直觉。</span></p><p><span class="marginnote">分块可以类比搬砖上楼：别想着一次搬整栋楼的砖（整个矩阵放不进缓存），而是把砖先码成单手拎得动的小垛（cache 装得下的 \\(B\\times B\\) 块），每次只在小垛上干活，干完一垛再换下一垛——来回跑腿（访存）的次数大幅下降。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对完美嵌套估计依赖（下标为 IV 仿射时）。尝试交换使最内层连续。选 \\(B\\) 使 \\(B^2\\) 个元素进 cache。带规约的循环：依赖是特殊的，常仍可分块（浮点结合律问题点名 fast-math）。</p>',12)),(i(),r(E,null,{default:t(()=>[s(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEST%5B%22%E5%BE%AA%E7%8E%AF%E5%B5%8C%E5%A5%97%22%5D%20--%3E%20DEP%5B%22%E4%BE%9D%E8%B5%96%E5%90%91%E9%87%8F%22%5D%0A%20%20DEP%20--%3E%20INT%5B%22%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20DEP%20--%3E%20TILE%5B%22%E5%88%86%E5%9D%97%22%5D%0A%20%20INT%20--%3E%20LOC%5B%22stride-1%20%2F%20%E5%A4%8D%E7%94%A8%22%5D%0A%20%20TILE%20--%3E%20LOC%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 LICM：分块后不变式仍外提。不要在有未知函数调用的循环上盲交换。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：L1 数据缓存 32 KB，double 占 8 字节，取 \\(B=64\\)，一块 \\(64\\times64\\) 的子矩阵就是 \\(64\\times64\\times8=32\\) KB，恰好塞满 L1。「选 \\(B\\) 使 \\(B^2\\) 个元素进 cache」就是这么算的，不是拍脑袋。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[l("以矩阵乘为例，"),e("code",null,"i,j,k"),l(" 与 "),e("code",null,"i,k,j"),l(" 两种写法算的是同一个 \\(C\\)，缓存遭遇战却完全不同。")],-1)),(i(),r(E,null,{default:t(()=>[s(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20IJK%5B%22i%2Cj%2Ck%20%E9%A1%BA%E5%BA%8F%EF%BC%9Ak%20%E5%9C%A8%E6%9C%80%E5%86%85%E5%B1%82%22%5D%20--%3E%20COL%5B%22B%20%E6%8C%89%20k%20%E8%B5%B0%E5%88%97%EF%BC%8C%E6%AD%A5%E9%95%BF%20%3D%20N%22%5D%0A%20%20COL%20--%3E%20MISS%5B%22%E6%AF%8F%E6%AD%A5%E8%B7%A8%E4%B8%80%E8%A1%8C%EF%BC%8C%E7%BC%93%E5%AD%98%E9%A2%91%E9%A2%91%E4%B8%8D%E5%91%BD%E4%B8%AD%22%5D%0A%20%20IKJ%5B%22i%2Ck%2Cj%20%E9%A1%BA%E5%BA%8F%EF%BC%9Aj%20%E5%9C%A8%E6%9C%80%E5%86%85%E5%B1%82%22%5D%20--%3E%20ROW%5B%22B%20%E6%8C%89%20j%20%E8%B5%B0%E8%A1%8C%EF%BC%8C%E6%AD%A5%E9%95%BF%20%3D%201%22%5D%0A%20%20ROW%20--%3E%20HIT%5B%22%E8%BF%9E%E7%BB%AD%E8%AE%BF%E9%97%AE%EF%BC%8C%E6%95%B4%E8%A1%8C%E7%95%99%E5%9C%A8%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">初学者容易以为换循环顺序「最多影响性能，不会出错」。对带依赖的嵌套（递推、规约）换序会直接改语义；即使合法，浮点加法不满足结合律，换求和顺序也可能让最后一位不同——这正是 fast-math 开关存在的语境。</span></p><p>非法交换会改语义（不只变慢）。编译器必须放弃或用运行时别名检查（版本化循环）。数组可重叠时需<a href="/cs/alias-analysis">别名</a>。</p><p>寄存器 tiling 是把块再缩到寄存器文件，与分配交互。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整多面体 ILP。后课默认：仿射嵌套可试交换与分块。下一课自动向量化：最内层变成 SIMD。</p><p>也不把 GPU 的 block 当本课 tiling 的定义，尽管同思想。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交换改嵌套顺序以对齐连续访问；合法性看依赖。</li><li>分块按缓存切迭代空间。</li><li>与展开不同层；可组合。</li><li>出处：Wolf and Lam, 1991；Allen and Kennedy；龙书。</li></ul>',8))])}const T=d(A,[["render",c]]);export{g as __pageData,T as default};
